import base64
import io
import pickle
from pickle import Unpickler


class SafeUnpickler(Unpickler):
    """Restrict unpickling to safe built-in types only."""
    SAFE_TYPES = {
        'builtins': {
            'dict', 'list', 'tuple', 'str', 'int', 'float', 'bool',
            'NoneType', 'set', 'frozenset'
        }
    }

    def find_class(self, module, name):
        if module in self.SAFE_TYPES and name in self.SAFE_TYPES[module]:
            return getattr(__builtins__, name)
        raise pickle.UnpicklingError(f"Unsafe type: {module}.{name}")


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded cookie string.

    Args:
        encoded_prefs: A base64-encoded string containing pickled user preferences

    Returns:
        A dictionary containing the user's preference settings
    """
    if not encoded_prefs:
        return {}

    try:
        # Decode the base64 string
        decoded_data = base64.b64decode(encoded_prefs)

        # Deserialize using a safe unpickler to prevent arbitrary code execution
        preferences = SafeUnpickler(io.BytesIO(decoded_data)).load()

        # Ensure the result is a dictionary
        if not isinstance(preferences, dict):
            return {}
    except (base64.binascii.Error, pickle.UnpicklingError, EOFError, Exception):
        # Return empty dict on any decoding/parsing error
        return {}

    return preferences

