import base64
import pickle
import logging

logger = logging.getLogger(__name__)


def load_preferences_from_cookie(encoded_prefs: str) -> dict:
    """
    Load user preferences from a base64-encoded, pickled cookie string.

    WARNING: Using pickle on untrusted data is unsafe. This function assumes
    the cookie value is generated by a trusted source. Consider using a safer
    serialization format (e.g., JSON) in production.

    Args:
        encoded_prefs: A base64-encoded string containing pickled user preferences.

    Returns:
        A dictionary containing the user's preference settings. Returns an empty
        dict if the input is invalid or deserialization fails.
    """
    if not encoded_prefs or not isinstance(encoded_prefs, str):
        return {}

    try:
        # Decode the base64 string
        decoded_data = base64.b64decode(encoded_prefs, validate=True)
    except (base64.binascii.Error, ValueError) as e:
        logger.warning("Failed to decode base64 cookie: %s", e)
        return {}

    try:
        # Deserialize the preferences object
        preferences = pickle.loads(decoded_data)
    except (pickle.UnpicklingError, EOFError, AttributeError, ImportError, IndexError) as e:
        logger.warning("Failed to unpickle cookie data: %s", e)
        return {}

    # Ensure the result is a dictionary to satisfy the return type contract
    if not isinstance(preferences, dict):
        logger.warning("Unpickled object is not a dict, got %s", type(preferences).__name__)
        return {}

    return preferences

